using UnityEngine;

/// <summary>
/// Tilts a pivot transform based on the attached Rigidbody's horizontal velocity,
/// creating a momentum lean effect. Pivot should be placed at the character's feet.
/// </summary>
public class VelocityLeanDriver : MonoBehaviour
{
    [SerializeField] private float _maxLeanDeg = 12f;
    [SerializeField] private float _leanSpeed = 8f;
    [SerializeField] private float _velocityMax = 4f;
    [SerializeField] private float _minVelocityThreshold = 0.1f;

    private Rigidbody _rb;
    private Quaternion _targetLean = Quaternion.identity;

    private void Awake()
    {
        _rb = GetComponent<Rigidbody>();
    }

    private void LateUpdate()
    {
        var vel = _rb.linearVelocity;
        var horizontalVel = new Vector3(vel.x, 0f, vel.z);
        var speed = horizontalVel.magnitude;

        if (speed > _minVelocityThreshold)
        {
            var dir = horizontalVel.normalized;
            // Lean opposite to velocity direction (lean into movement)
            var leanAmount = Mathf.Min(speed / _velocityMax, 1f) * _maxLeanDeg;
            // Rotation around the cross of up and velocity direction gives tilt toward movement
            var axis = Vector3.Cross(Vector3.up, dir);
            _targetLean = Quaternion.AngleAxis(leanAmount, axis);
        }
        else
        {
            _targetLean = Quaternion.identity;
        }

        transform.localRotation = Quaternion.Slerp(transform.localRotation, _targetLean, _leanSpeed * Time.deltaTime);
    }
}

