var player = UnityEngine.Object.FindObjectOfType<SolarpunkCharacterController>()?.gameObject;
if (player == null)
{
    UnityEngine.Debug.LogError("Player not found!");
    return;
}

// Calculate foot position: capsule center - half height
var capsule = player.GetComponent<UnityEngine.CapsuleCollider>();
var rb = player.GetComponent<UnityEngine.Rigidbody>();
float footY = player.transform.position.y - (capsule != null ? capsule.height / 2f : 0f);

// Create the lean pivot at the foot position
var pivot = new UnityEngine.GameObject("PlayerLeanPivot");
pivot.transform.position = new UnityEngine.Vector3(player.transform.position.x, footY, player.transform.position.z);
pivot.transform.rotation = UnityEngine.Quaternion.identity;

// Reparent: pivot takes Player's current world position anchor
// Player becomes child of pivot
player.transform.SetParent(pivot.transform, true); // worldPositionStays = true

// Add the VelocityLeanDriver component
pivot.AddComponent<VelocityLeanDriver>();

UnityEngine.Debug.Log($"Created PlayerLeanPivot at Y={footY:F2}, Player reparented under it.");

