    private Rigidbody _rb;
    private float _footOffsetY;
    private Quaternion _targetLean = Quaternion.identity;

    private void Awake()
    {
        _rb = GetComponentInChildren<Rigidbody>();
        // Distance from the Rigidbody's position down to the character's feet
        var capsule = _rb.GetComponentInChildren<Collider>();
        _footOffsetY = capsule != null ? capsule.bounds.extents.y : 0f;
    }

    private void LateUpdate()
    {
        // Keep pivot at the Rigidbody's foot position so lean pivots from the base
        var rbPos = _rb.position;
        transform.position = new Vector3(rbPos.x, rbPos.y - _footOffsetY, rbPos.z);

        var vel = _rb.velocity;
        var horizontalVel = new Vector3(vel.x, 0f, vel.z);
        var speed = horizontalVel.magnitude;

        if (speed > _minVelocityThreshold)
        {
            var dir = horizontalVel.normalized;
            var leanAmount = Mathf.Min(speed / _velocityMax, 1f) * _maxLeanDeg;
            var axis = Vector3.Cross(Vector3.up, dir);
            _targetLean = Quaternion.AngleAxis(leanAmount, axis);
        }
        else
        {
            _targetLean = Quaternion.identity;
        }

        transform.rotation = Quaternion.Slerp(transform.rotation, _targetLean, _leanSpeed * Time.deltaTime);
    }
}

