// Undo: unparent Player from PlayerLeanPivot, then delete the pivot
var player = UnityEngine.Object.FindObjectOfType<SolarpunkCharacterController>()?.gameObject;
if (player == null) { UnityEngine.Debug.LogError("No Player"); return; }

var pivot = player.transform.parent;
if (pivot != null && pivot.name == "PlayerLeanPivot")
{
    player.transform.SetParent(null, true);
    UnityEngine.Object.DestroyImmediate(pivot.gameObject);
    UnityEngine.Debug.Log("Removed PlayerLeanPivot, Player is root again.");
}
else
{
    UnityEngine.Debug.Log("PlayerLeanPivot not found as parent, skipping.");
}

