using UnityEngine;

public class Billboard : MonoBehaviour
{
    private Camera _mainCamera;

    private void Start()
    {
        _mainCamera = Camera.main;
    }

    private void LateUpdate()
    {
        if (_mainCamera == null) return;

        Vector3 directionToCamera = _mainCamera.transform.position - transform.position;

        float horizontalDist = new Vector2(directionToCamera.x, directionToCamera.z).magnitude;
        float pitchAngle = Mathf.Atan2(directionToCamera.y, horizontalDist) * Mathf.Rad2Deg;

        transform.rotation = Quaternion.Euler(pitchAngle, transform.eulerAngles.y, 0f);
    }
}

using UnityEngine;

/// <summary>
/// Tilts a pivot transform based on the attached Rigidbody's horizontal velocity,
/// creating a momentum lean effect. Pivot should be placed at the character's feet.
/// </summary>
public class VelocityLeanDriver : MonoBehaviour
{
    [SerializeField] private float _maxLeanDeg = 12f;
    [SerializeField] private float _leanSpeed = 8f;
    [SerializeField] private float _velocityMax = 4f;
    [SerializeField] private float _minVelocityThreshold = 0.1f;

    private Rigidbody _rb;
    private Transform _rbTransform;
    private float _footOffsetY;
    private Quaternion _targetLean = Quaternion.identity;

    private void Awake()
    {
        _rb = GetComponentInChildren<Rigidbody>();
        _rbTransform = _rb.transform;
        var capsule = _rb.GetComponent<Collider>();
        _footOffsetY = capsule != null ? capsule.bounds.extents.y : 0f;
    }

    private void LateUpdate()
    {
        // Position pivot at the Rigidbody's foot so tilt pivots from the base
        var rbPos = _rb.position;
        transform.position = new Vector3(rbPos.x, rbPos.y - _footOffsetY, rbPos.z);

        // Keep the Rigidbody child at the correct offset above the pivot
        _rbTransform.localPosition = new Vector3(0f, _footOffsetY, 0f);

        var vel = _rb.velocity;
        var horizontalVel = new Vector3(vel.x, 0f, vel.z);
        var speed = horizontalVel.magnitude;

        if (speed > _minVelocityThreshold)
        {
            var dir = horizontalVel.normalized;
            var leanAmount = Mathf.Min(speed / _velocityMax, 1f) * _maxLeanDeg;
            var axis = Vector3.Cross(Vector3.up, dir);
            _targetLean = Quaternion.AngleAxis(leanAmount, axis);
        }
        else
        {
            _targetLean = Quaternion.identity;
        }

        transform.rotation = Quaternion.Slerp(transform.rotation, _targetLean, _leanSpeed * Time.deltaTime);
    }
}

