var player = UnityEngine.Object.FindObjectOfType<SolarpunkCharacterController>()?.gameObject;
if (player == null) { UnityEngine.Debug.LogError("No Player"); return; }

var visual = player.transform.Find("New_Visual");
if (visual == null) { UnityEngine.Debug.LogError("No New_Visual"); return; }

// Capsule height to compute foot offset
var capsule = player.GetComponent<UnityEngine.CapsuleCollider>();
float halfHeight = capsule != null ? capsule.height / 2f : 0.455f;

// Create visual lean pivot at the feet
var pivot = new UnityEngine.GameObject("VisualLeanPivot");
pivot.transform.SetParent(player.transform, false);
pivot.transform.localPosition = new UnityEngine.Vector3(0f, -halfHeight, 0f);
pivot.transform.localRotation = Quaternion.identity;
pivot.transform.localScale = UnityEngine.Vector3.one;

// Reparent New_Visual under the pivot, offset up so world position is preserved
visual.SetParent(pivot.transform, true); // worldPositionStays = true

// Add VelocityLeanDriver and wire the Rigidbody reference
var leanDriver = pivot.AddComponent<VelocityLeanDriver>();
var rb = player.GetComponent<UnityEngine.Rigidbody>();

// Use SerializedObject to set the _rb field at edit time
var so = new UnityEditor.SerializedObject(leanDriver);
so.FindProperty("_rb").objectReferenceValue = rb;
so.ApplyModifiedProperties();

UnityEngine.Debug.Log($"Created VisualLeanPivot at localY={-halfHeight:F3}, New_Visual reparented, Rigidbody wired.");

