var player = UnityEngine.Object.FindObjectOfType<SolarpunkCharacterController>()?.gameObject;
if (player == null) { UnityEngine.Debug.LogError("No Player"); return; }

// Remove the VisualLeanPivot - reparent New_Visual back under Player
var pivot = player.transform.Find("VisualLeanPivot");
if (pivot != null)
{
    var visual = pivot.Find("New_Visual");
    if (visual != null)
    {
        visual.SetParent(player.transform, true); // worldPositionStays
        UnityEngine.Debug.Log("Reparented New_Visual back to Player.");
    }
    UnityEngine.Object.DestroyImmediate(pivot.gameObject);
    UnityEngine.Debug.Log("Destroyed VisualLeanPivot.");
}

// Add VelocityLeanDriver to New_Visual
var newVisual = player.transform.Find("New_Visual");
if (newVisual == null) { UnityEngine.Debug.LogError("No New_Visual"); return; }

// Remove any existing VelocityLeanDriver (from old setup)
var existing = newVisual.GetComponent<VelocityLeanDriver>();
if (existing != null) UnityEngine.Object.DestroyImmediate(existing);

var leanDriver = newVisual.gameObject.AddComponent<VelocityLeanDriver>();
var rb = player.GetComponent<UnityEngine.Rigidbody>();

var so = new UnityEditor.SerializedObject(leanDriver);
so.FindProperty("_rb").objectReferenceValue = rb;
so.ApplyModifiedProperties();

UnityEngine.Debug.Log("Added VelocityLeanDriver to New_Visual with Rigidbody reference.");

