private void LateUpdate()
{
    if (_rb == null) return;

    var vel = _rb.velocity;
    var horizontalVel = new Vector3(vel.x, 0f, vel.z);
    var speed = horizontalVel.magnitude;

    if (speed > _minVelocityThreshold)
    {
        var dir = horizontalVel.normalized;
        var leanAmount = Mathf.Min(speed / _velocityMax, 1f) * _maxLeanDeg;
        var axis = Vector3.Cross(Vector3.up, dir);
        _targetLean = Quaternion.AngleAxis(leanAmount, axis);
    }
    else
    {
        _targetLean = Quaternion.identity;
    }

    _currentLean = Quaternion.Slerp(_currentLean, _targetLean, _leanSpeed * Time.deltaTime);

    var euler = _currentLean.eulerAngles;
    Debug.Log($"[LeanDriver] speed={speed:F2} target={_targetLean.eulerAngles} current={euler}");

    // Compose lean with the Billboard's rotation (Billboard runs first via default order)
    transform.rotation = _currentLean * transform.rotation;

    // Offset position to simulate pivot-at-feet
    Vector3 feetOffset = new Vector3(0f, -_footOffsetY, 0f);
    transform.position += _currentLean * feetOffset - feetOffset;
}

