        Debug.Log($"[Lean] speed={speed:F2} lean={_currentLean.eulerAngles} offset={_currentLean * new Vector3(0,-_footOffsetY,0) - new Vector3(0,-_footOffsetY,0)}");

    // Compose lean with the Billboard's rotation (Billboard runs first via default order)
    transform.rotation = _currentLean * transform.rotation;

    // Offset position so the lean pivots from the feet (not the center)
    Vector3 feetOffset = new Vector3(0f, -_footOffsetY, 0f);
    Vector3 leanOffset = _currentLean * feetOffset - feetOffset;
    transform.localPosition = _baseLocalPos + leanOffset;
}

