using UnityEngine;

/// <summary>
/// Applies a momentum lean to a billboarded visual by composing a tilt rotation
/// after the Billboard component has set the facing. Runs after Billboard via
/// DefaultExecutionOrder. The lean pivots from the character's feet using a
/// configurable height offset.
/// </summary>
[DefaultExecutionOrder(100)]
public class VelocityLeanDriver : MonoBehaviour
{
    [SerializeField] private Rigidbody _rb;
    [SerializeField] private float _maxLeanDeg = 12f;
    [SerializeField] private float _leanSpeed = 8f;
    [SerializeField] private float _velocityMax = 4f;
    [SerializeField] private float _minVelocityThreshold = 0.1f;
    [Tooltip("Vertical distance from the transform's origin down to the character's feet. Used to offset position so the lean pivots from the base.")]
    [SerializeField] private float _footOffsetY = 0.455f;

    private Quaternion _currentLean = Quaternion.identity;
    private Quaternion _targetLean = Quaternion.identity;
    private Vector3 _baseLocalPos;

    private void Awake()
    {
        _baseLocalPos = transform.localPosition;
    }

    private void LateUpdate()
    {
        if (_rb == null) return;

        var vel = _rb.velocity;
        var horizontalVel = new Vector3(vel.x, 0f, vel.z);
        var speed = horizontalVel.magnitude;

        if (speed > _minVelocityThreshold)
        {
            var dir = horizontalVel.normalized;
            var leanAmount = Mathf.Min(speed / _velocityMax, 1f) * _maxLeanDeg;
            var axis = Vector3.Cross(dir, Vector3.up);
            _targetLean = Quaternion.AngleAxis(leanAmount, axis);
        }
        else
        {
            _targetLean = Quaternion.identity;
        }

        _currentLean = Quaternion.Slerp(_currentLean, _targetLean, _leanSpeed * Time.deltaTime);

        if (speed > 0.01f)
            Debug.Log($"[Lean] speed={speed:F2} lean={_currentLean.eulerAngles} offset={_currentLean * new Vector3(0,-_footOffsetY,0) - new Vector3(0,-_footOffsetY,0)}");

        // Compose lean with the Billboard's rotation (Billboard runs first via default order)
        transform.rotation = _currentLean * transform.rotation;

        // Offset position so the lean pivots from the feet (not the center)
        Vector3 feetOffset = new Vector3(0f, -_footOffsetY, 0f);
        Vector3 leanOffset = _currentLean * feetOffset - feetOffset;
        transform.localPosition = _baseLocalPos + leanOffset;
    }
}

