[Header("Petal (spring dynamics)")]
[Tooltip("The petal transform. Dynamically reparented to the active view's Head/PetalPivot at runtime.")]
[SerializeField] private Transform _petal;
[Tooltip("Spring stiffness — how strongly the petal pulls back to rest. Higher = snappier.")]
[SerializeField, Range(10f, 300f)] private float _petalStiffness = 120f;
[Tooltip("Spring damping — how quickly oscillation dies out. Lower = more jiggle.")]
[SerializeField, Range(1f, 30f)] private float _petalDamping = 8f;
[Tooltip("How much the petal's world-space movement amplifies into lean (degrees per unit of movement delta).")]
[SerializeField, Range(0f, 500f)] private float _petalSensitivity = 150f;
[Tooltip("Max Z-rotation the spring can produce (degrees). Clamps overshoot.")]
[SerializeField, Range(0f, 90f)] private float _petalMaxLeanDeg = 45f;

// ── Petal spring state ─────────────────────────────────────────────────────
private float _petalAngle;      // current Z rotation in degrees
private float _petalVelocity;   // angular velocity (deg/s) for the spring
private Vector3 _petalPrevWorldPos;

// ── Petal tracking ──────────────────────────────────────────────────────────

/// <summary>
/// Springs the petal's Z-rotation based on how much its anchor (PetalPivot)
/// has moved since last frame. This gives lag + overshoot + settle — the
/// classic secondary motion jiggle.
/// </summary>
private void UpdatePetal()
{
    if (_petal == null) return;
    var head = FindActiveHead();
    if (head == null) return;

    var pivot = head.Find("PetalPivot");
    if (pivot == null) return;

    if (_petal.parent != pivot)
    {
        _petal.SetParent(pivot, false);
        _petal.localPosition = Vector3.zero;
        _petalPrevWorldPos = _petal.position;
        _petalAngle = 0f;
        _petalVelocity = 0f;
    }

    // Measure how much the petal's anchor moved in world space this frame
    var worldPos = _petal.position;
    var delta = worldPos - _petalPrevWorldPos;
    _petalPrevWorldPos = worldPos;

    // Convert horizontal movement into a spring "kick" — lean opposite to movement
    // so the petal drags behind. Z-axis lean for left/right motion.
    float kick = -delta.x * _petalSensitivity;

    // Underdamped spring: acceleration = -stiffness * displacement - damping * velocity + kick
    float dt = Time.deltaTime;
    float acceleration = -_petalStiffness * _petalAngle * Mathf.Deg2Rad
                          - _petalDamping * _petalVelocity
                          + kick;
    _petalVelocity += acceleration * dt;
    _petalAngle += _petalVelocity * dt;

    // Clamp to prevent extreme values
    _petalAngle = Mathf.Clamp(_petalAngle, -_petalMaxLeanDeg, _petalMaxLeanDeg);

    _petal.localRotation = Quaternion.Euler(0f, 0f, _petalAngle);
}

