private void UpdatePetal()
{
    if (_petal == null) return;
    var head = FindActiveHead();
    if (head == null) return;

    var pivot = head.Find("PetalPivot");
    if (pivot == null) return;

    if (_petal.parent != pivot)
    {
        _petal.SetParent(pivot, false);
        _petal.localPosition = Vector3.zero;
        _petalPrevWorldPos = pivot.position;
        _petalAngle = 0f;
        _petalVelocity = 0f;
    }

    // Measure how much the PetalPivot moved in world space this frame
    var worldPos = pivot.position;
    var delta = worldPos - _petalPrevWorldPos;
    _petalPrevWorldPos = worldPos;

    // Convert horizontal movement into a spring "kick" — lean opposite to movement
    // so the petal drags behind. Z-axis lean for left/right motion.
    float kick = -delta.x * _petalSensitivity;

    // Underdamped spring: acceleration = -stiffness * displacement - damping * velocity + kick
    float dt = Time.deltaTime;
    float acceleration = -_petalStiffness * _petalAngle * Mathf.Deg2Rad
                          - _petalDamping * _petalVelocity
                          + kick;
    _petalVelocity += acceleration * dt;
    _petalAngle += _petalVelocity * dt;

    // Clamp to prevent extreme values
    _petalAngle = Mathf.Clamp(_petalAngle, -_petalMaxLeanDeg, _petalMaxLeanDeg);

    pivot.localRotation = Quaternion.Euler(0f, 0f, _petalAngle);
}

