// ── Petal spring state ─────────────────────────────────────────────────────
private float _petalAngle;      // current Z rotation in degrees
private float _petalVelocity;   // angular velocity (deg/s) for the spring
private Quaternion _petalPrevParentRot;

// ── Petal tracking ──────────────────────────────────────────────────────────

/// <summary>
/// Springs the petal's Z-rotation based on the parent Head's rotation and
/// the character's horizontal velocity. This gives lag + overshoot + settle —
/// the classic secondary motion jiggle.
/// </summary>
private void UpdatePetal()
{
    if (_petal == null) return;
    var head = FindActiveHead();
    if (head == null) return;

    var pivot = head.Find("PetalPivot");
    if (pivot == null) return;

    if (_petal.parent != pivot)
    {
        _petal.SetParent(pivot, false);
        _petal.localPosition = Vector3.zero;
        _petalPrevParentRot = head.localRotation;
        _petalAngle = 0f;
        _petalVelocity = 0f;
    }

    // Measure how much the parent (Head) rotated since last frame
    var deltaRot = head.localRotation * Quaternion.Inverse(_petalPrevParentRot);
    _petalPrevParentRot = head.localRotation;

    // Convert the delta rotation to an euler approximation and extract Z tilt
    deltaRot.ToAngleAxis(out float deltaAngle, out Vector3 deltaAxis);
    // Sign the angle so positive Z-axis rotation = lean right
    float signedDeltaZ = Vector3.Dot(deltaAxis, Vector3.forward) > 0 ? deltaAngle : -deltaAngle;

    // Also use horizontal velocity for directional lean
    var vel = _controller.MoveInput;
    float velKick = -vel.x * _petalSensitivity * 0.01f;

    // Spring kick: opposite to parent rotation (drag behind) + velocity influence
    float kick = -signedDeltaZ * _petalSensitivity * 0.1f + velKick;

    // Underdamped spring: acceleration = -stiffness * displacement - damping * velocity + kick
    float dt = Time.deltaTime;
    float acceleration = -_petalStiffness * _petalAngle * Mathf.Deg2Rad
                          - _petalDamping * _petalVelocity
                          + kick;
    _petalVelocity += acceleration * dt;
    _petalAngle += _petalVelocity * dt;

    // Clamp to prevent extreme values
    _petalAngle = Mathf.Clamp(_petalAngle, -_petalMaxLeanDeg, _petalMaxLeanDeg);

    pivot.localRotation = Quaternion.Euler(0f, 0f, _petalAngle);
}

