// ── Limb walk cycle procedural animation ───────────────────────────────────

/// <summary>
/// Walk cycle for feet and arms via pivot transforms under Head.
/// Legs alternate (180° out of phase). Arms swing opposite to same-side foot.
/// Rotation axis is driven by MOVEMENT direction, not view facing:
///   - Running along Z → legs swing around X-axis
///   - Running along X → legs swing around Z-axis
///   - Diagonal → blended proportionally
/// Y rotation is never touched.
/// </summary>
private void UpdateLimbs(float speed)
{
    var head = FindActiveHead();
    if (head == null) return;

    float sf = Mathf.Clamp01(speed);
    if (sf < 0.01f) return; // no motion when still

    var input = _controller.MoveInput;
    var dir = new Vector2(input.x, input.z);
    float dirMag = dir.magnitude;
    if (dirMag < 0.01f) return;

    dir /= dirMag; // normalize

    // How much swing goes on X-axis vs Z-axis based on movement direction
    // |dir.y| (Z component) → X-axis swing; |dir.x| (X component) → Z-axis swing
    float xWeight = Mathf.Abs(dir.y); // running forward/back → X-axis rotation
    float zWeight = Mathf.Abs(dir.x); // running left/right → Z-axis rotation

    float t = Time.time * _limbCycleSpeed;

    // Legs alternate 180° out of phase
    float leftPhase  = Mathf.Sin(t);
    float rightPhase = -leftPhase; // opposite

    foreach (Transform pivot in head)
    {
        string n = pivot.name;
        if (n == "PetalPivot") continue;

        if (n == "LeftLegPivot")
        {
            float tilt = -leftPhase * _footTiltDeg * sf;
            pivot.localRotation = Quaternion.Euler(tilt * xWeight, 0f, tilt * zWeight);
        }
        else if (n == "RightLegPivot")
        {
            float tilt = -rightPhase * _footTiltDeg * sf;
            pivot.localRotation = Quaternion.Euler(tilt * xWeight, 0f, tilt * zWeight);
        }
        else if (n == "RightArmPivot")
        {
            // Right arm swings with left foot (same phase, opposite direction)
            float tilt = leftPhase * _armTiltDeg * sf;
            pivot.localRotation = Quaternion.Euler(tilt * xWeight, 0f, tilt * zWeight);
        }
        else if (n == "LeftArmPivot")
        {
            // Left arm swings with right foot (same phase, opposite direction)
            float tilt = rightPhase * _armTiltDeg * sf;
            pivot.localRotation = Quaternion.Euler(tilt * xWeight, 0f, tilt * zWeight);
        }
    }
}

