/// <summary>
/// Walk cycle for feet and arms via pivot transforms under Head.
/// Legs alternate (180° out of phase). Arms swing opposite to same-side foot.
/// Rotation axis driven by MOVEMENT direction:
///   Running Z → X-axis swing; Running X → Z-axis swing; Diagonal → blended.
/// Y rotation is never touched.
/// </summary>
private void UpdateLimbs(float speed)
{
    var head = FindActiveHead();
    if (head == null) return;

    float sf = Mathf.Clamp01(speed);
    if (sf < 0.01f) return;

    var input = _controller.MoveInput;
    var dir = new Vector2(input.x, input.z);
    float dirMag = dir.magnitude;
    if (dirMag < 0.01f) return;
    dir /= dirMag;

    float xWeight = Mathf.Abs(dir.y); // Z movement → X-axis rotation
    float zWeight = Mathf.Abs(dir.x); // X movement → Z-axis rotation

    float t = Time.time * _limbCycleSpeed;
    float leftPhase  = Mathf.Sin(t);
    float rightPhase = -leftPhase;

    foreach (Transform pivot in head)
    {
        string n = pivot.name;
        if (n == "PetalPivot") continue;

        if (n == "LeftLegPivot")
        {
            float tilt = -leftPhase * _footTiltDeg * sf;
            pivot.localRotation = Quaternion.Euler(tilt * xWeight, 0f, tilt * zWeight);
        }
        else if (n == "RightLegPivot")
        {
            float tilt = -rightPhase * _footTiltDeg * sf;
            pivot.localRotation = Quaternion.Euler(tilt * xWeight, 0f, tilt * zWeight);
        }
        else if (n == "RightArmPivot")
        {
            float tilt = leftPhase * _armTiltDeg * sf;
            pivot.localRotation = Quaternion.Euler(tilt * xWeight, 0f, tilt * zWeight);
        }
        else if (n == "LeftArmPivot")
        {
            float tilt = rightPhase * _armTiltDeg * sf;
            pivot.localRotation = Quaternion.Euler(tilt * xWeight, 0f, tilt * zWeight);
        }
    }
}

